import unreal_engine as ue
from unreal_engine.classes import DataTable

root = ue.get_project_root()
tables = [
    root + '/Asset/Data/Table/Customized/LotteryAwardConfig',
    root + '/Asset/Data/Table/UGCBattleItem',
    root + '/Asset/Data/Table/UGCObject',
    root + '/Asset/Data/Table/CheckinTable',
]

def walk(value, prefix=''):
    hits = []
    if isinstance(value, str):
        if '/Douluo/' in value:
            hits.append((prefix, value))
    elif isinstance(value, dict):
        for k, v in value.items():
            hits.extend(walk(v, prefix + '.' + str(k) if prefix else str(k)))
    elif isinstance(value, (list, tuple)):
        for i, v in enumerate(value):
            hits.extend(walk(v, prefix + '[' + str(i) + ']'))
    else:
        try:
            for name in value.properties():
                hits.extend(walk(getattr(value, name), prefix + '.' + str(name) if prefix else str(name)))
        except Exception:
            pass
    return hits

summary = []
for path in tables:
    dt = ue.load_object(DataTable, path)
    if not dt:
        summary.append({'table': path, 'loaded': False})
        continue
    data = ue.data_table_as_dict(dt)
    table_hits = []
    for row_name, row in data.items():
        for field, val in walk(row):
            table_hits.append({'row': str(row_name), 'field': field, 'value': val})
    summary.append({'table': path, 'loaded': True, 'row_count': len(data), 'hit_count': len(table_hits), 'hits': table_hits[:20]})

__askq_result = summary
